////REALLY SIMPLE DRAWING




void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
        uv = uv*2.0f - 1.0f;
         uv.x *= iResolution.x/iResolution.y;
          float h = sqrt(-(uv.x*uv.x)-(uv.y*uv.y)+(0.5f));
            float dx = -uv.x/h;
            float dy = -uv.y/h;
             vec3 n = normalize(vec3(-dx,-dy,1.0f));
               n = (h > 0.0) ? n:vec3(0,0,1);
               n = n.xzy;

               vec3 pos = vec3(uv,h);
               vec3 l = normalize(vec3(1,1,2));

                vec3 sp = pos+l;
                float hs = 1.0f-sqrt(-(sp.x*sp.x)-(sp.y*sp.y)+(0.3f));
                float shadowis = 1.0f - float(hs > 0.0f);


               float lambert = dot(l,n);
               if(h > 0.0f) {

                  lambert = max(lambert,0.04f);
               } else {
                  lambert *= shadowis;
                   }



    fragColor = vec4(vec3(lambert),1.0);
}
